function usageSummary(){const u=world.usage||world.status?.usage||{},used=first(u,['used','used_units','units_used','month_used','monthly_used','month.used','monthly.used']),limit=first(u,['limit','quota','monthly_limit','month_limit','month.limit','monthly.limit']),explicit=first(u,['remaining','remaining_units','units_remaining','month_remaining','monthly_remaining','month.remaining','monthly.remaining']);const remaining=finite(explicit)!==null?explicit:finite(limit)!==null&&finite(used)!==null?Math.max(0,limit-used):null;const request=first(u,['this_call','request_units','requestUnits','units_this_request','request.units','request.cost','cost']);return{used,limit,remaining,request};}
