function errorMessage(error){const code=error?.code||'';if(code==='provider_blocked')return'访问被服务方阻止，需要所有者处理。';if(code==='same_origin_required')return'这个面板需要由同一个本地服务器打开。';if(/revision|stale|conflict/.test(code))return'状态版本已更新。请先读取服务器缓存，确认上一回是否已推进。';if(/quota|limit|month|units/.test(code))return'免费用量或调用频率已达限制。不会自动付费，也不会自动重试。';if(code==='local_unavailable')return'本地 API 服务尚未接上，唐的主线仍可正常使用。';return error?.message||'这次连接未完成；没有自动重试。';}
function errorMarkup(){return world.error?`<div class="world-error" role="alert"><strong>${E(errorMessage(world.error))}</strong>${world.payload?'<p>下面保留最近一次已取得的缓存。</p>':''}<details><summary>查看服务返回的原因</summary><p>${E(world.error.message||'未返回更多说明')} ${world.error.code?`（${E(world.error.code)}）`:''}</p></details></div>`:'';}
async function request(action,body){const endpoint='/api/world/'+action;let response;try{response=await fetch(endpoint,{method:action==='status'?'GET':'POST',credentials:'same-origin',headers:action==='status'?{}:{'Content-Type':'application/json'},...(action==='status'?{}:{body:JSON.stringify(body||{})})});}catch(_){throw{code:'connection_failed',message:'本地服务连接未完成。请读取缓存确认状态，不要重复推进。'};}let value;try{value=await response.json();}catch(_){throw{code:'local_unavailable',message:'本地接口没有返回可识别的 JSON，请确认服务已启动。'};}if(value?.usage)world.usage=value.usage;if(!response.ok||value?.error){const err=value?.error;throw typeof err==='object'?err:{code:value?.code||'request_failed',message:typeof err==='string'?err:'服务未完成这次请求。'};}return value;}
