function eventText(event){if(Array.isArray(event))return label(event[1]);if(typeof event==='string')return event;if(!event||typeof event!=='object')return'';return label(event.text||event.message||event.description||event.summary||event.title||event.label);}
function choices(){const d=world.payload?.decision;if(!d)return[];const raw=d.choices||d.options||[];if(Array.isArray(raw))return raw.map(o=>typeof o==='string'?null:{...o,key:o.key??o.id??o.value}).filter(o=>o&&o.key!==undefined&&o.key!==null);if(raw&&typeof raw==='object')return Object.entries(raw).map(([key,o])=>typeof o==='string'?{key,label:o}:{...o,key:o.key??key});return[];}
