function educationLabel(value){return({none:'未入学',primary:'小学',secondary:'中学',highschool:'高中',university:'大学',college:'大学',graduate:'研究生'})[label(value)]||label(value);}
function stateRows(){const s=sourceState();if(!s)return[];const rows=[['国家',countryOf(s)],['年份',label(yearOf(s))],['年龄',ageOf(s)===null?'':label(ageOf(s))+'岁'],['城市',label(first(s,['city','location.city','residence.city','location.name']))],['职业',label(first(s,['job_name','job.name.zh','job.name','job.label','occupation.name','occupation','job','work.job','vocation']))],['教育',educationLabel(first(s,['education.label','education.name','education','education_level']))]];return rows.filter(([,value])=>value);}
function statsMarkup(){const s=sourceState();if(!s)return'';const items=[['身体状态',['health','stats.health','status.health']],['幸福',['happiness','happy','stats.happiness','stats.happy']],['知识',['knowledge','stats.knowledge','stats.education']],['人际关系',['bonds','relationships','relations','stats.bonds','stats.relationships','stats.relations']]].map(([name,paths])=>({name,value:first(s,paths)})).filter(o=>finite(o.value)!==null);return items.length?`<div class="world-stat-list">${items.map(o=>`<div><span>${o.name}</span><i><b style="width:${Math.max(0,Math.min(100,o.value))}%"></b></i><strong>${E(Math.round(o.value))}</strong></div>`).join('')}</div><p class="world-small-note">这位虚构人物的官方引擎状态。</p>`:'';}
