function introMarkup(){return`<div class="world-intro"><h3>从同龄人的另一种处境出发</h3><p>API按26岁、男性、本科条件生成虚构人物，供你对照生活的不同可能；唐的真实记录与紫微主线各自保留。</p><p>开启后先读取已有会话。生成、推进和抉择由你点按发起，免费 units 的消耗随服务响应更新。</p><button id="world-enable" class="world-primary">开启官方 API 模式 →</button></div>`;}
function statusMarkup(){const configured=world.status?.configured,existing=world.sessionId||world.status?.existingSessionId||world.status?.currentSessionId;return`<div class="world-connection"><span>${configured?'服务器已配置官方连接':'等待服务器连接配置'}</span>${existing?`<button id="world-view">读取现有缓存（0 units） ↻</button>`:'<button id="world-status-refresh">重新读取连接状态 ↻</button>'}</div>`;}
