function openWorld(){pauseMain();const nav=$('#mobile-nav');if(nav)nav.hidden=true;$('#mobile-menu')?.setAttribute('aria-expanded','false');render();if(!dialog.open)dialog.showModal();}
async function activate(){if(world.busy)return;world.active=true;world.busy=true;world.error=null;render();try{const status=await request('status');world.status=status;world.usage=status.usage||world.usage;const sid=status.existingSessionId||status.currentSessionId||status.existingSession?.sessionId;if(sid){accept(await request('view',{sessionId:sid}),'view');}}catch(error){world.error=error;}finally{world.busy=false;render();}}
