async function startPerson(){if(world.busy)return;const country=$('#world-country')?.value||world.country,seed=Number($('#world-seed')?.value??world.seed);if(!Object.hasOwn(COUNTRY,country)||!Number.isInteger(seed)||seed<0||seed>4294967295){world.error={code:'invalid_input',message:'请选择允许的国家，并填写0至4294967295的整数种子。'};render();return;}world.country=country;world.seed=seed;world.busy=true;world.error=null;render();try{accept(await request('start',{country,age:26,sex:'male',education:'university',tries:5,seed}),'start');}catch(error){world.error=error;}finally{world.busy=false;render();}}
