$('#world-close').addEventListener('click',()=>dialog.close());$('#world-mini-open').addEventListener('click',openWorld);$$('[data-world-open]').forEach(b=>b.addEventListener('click',openWorld));dialog.addEventListener('close',pauseMain);render();
window.CISHENG_WORLD_UI={open:openWorld,getState:()=>({active:world.active,busy:world.busy,sessionId:world.sessionId,revision:revision(),hasPerson:Boolean(world.payload),error:world.error?.code||null})};
